INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('es', 'cv', '{"personal":{"name":"Benito Anagua","location":"Tarija, Bolivia","phone":"+591 72945548","email":"benito.anagua@gmail.com","website":"https://benitoanagua.pages.dev/","linkedin":"https://www.linkedin.com/in/benito-anagua","github":"https://github.com/benitoanagua","behance":"https://behance.net/benitoanagua","whatsapp":"https://wa.me/59172945548","maps":"https://www.google.com/maps/place/Tarija,+Bolivia"},"education":[{"degree":"Licenciatura en Ingeniería de Informática","institution":"Universidad Autónoma Juan Misael Saracho","year":"2012"},{"degree":"Inglés — A2","institution":"Funval Internacional","year":"2025"}],"focuses":[{"name":"developer","title":"Desarrollador Full Stack & Frontend Senior","subtitles":["Full Stack Development","Modern Web Architecture","Frontend Leadership"],"summary":"Desarrollador Full Stack Senior con 18 años de experiencia en desarrollo web moderno, especializado en Frontend. Experto en la creación de interfaces de usuario escalables, responsivas y de alto rendimiento utilizando Svelte, Vue.js y Blazor. Amplia experiencia en arquitectura frontend, optimización de aplicaciones web y desarrollo de sistemas de componentes reutilizables. Experiencia liderando proyectos técnicos, implementando mejores prácticas de desarrollo y colaborando con equipos multidisciplinarios en el ciclo completo SDLC.","skills":[{"category":"Frontend","items":["Svelte","Vue.js","Blazor","Astro.js","Flutter","HTML5","CSS3/SASS","JavaScript","TypeScript"]},{"category":"Backend","items":["C#","ASP.NET MVC","Entity Framework","PHP","Node.js","RESTful APIs"]},{"category":"Datos & DevOps","items":["PostgreSQL","MySQL","Docker","Ubuntu Server","Nginx","Git","GitLab","CI/CD"]},{"category":"Diseño","items":["Figma","Design Systems","Prototipado","Responsive Design"]},{"category":"Móvil, IA & Automatización","items":["Kotlin","Jetpack Compose","Firebase","Google Cloud Run","Elixir/OTP","Phoenix Framework","WhatsApp Business API","WooCommerce","WP-CLI","Claude","Gemini","Google Stitch"]}],"experiences":[{"company":"Freelance & Actualización Tecnológica","position":"Freelance Developer","period":"Dic 2024 - Jun 2026","description":"Durante el período independiente trabajé en desarrollo móvil Android con Kotlin y Jetpack Compose, integración de Firebase y despliegues en Google Cloud; desarrollé flujos conversacionales con Elixir/OTP, Phoenix y WhatsApp Business API; e implementé tiendas con WordPress, WooCommerce, Elementor y WP-CLI. También incorporé Claude, OpenCode, Gemini y Google Stitch en flujos de análisis, desarrollo y prototipado UX. Formación intensiva en inglés técnico: A2."},{"company":"ITGroup Systems","position":"Desarrollador Full Stack / Líder Frontend","period":"Oct 2016 - Dic 2024","description":"Lideré el desarrollo frontend de aplicaciones web empresariales utilizando Svelte, Vue.js y Blazor, logrando interfaces de alto rendimiento y tiempos de carga optimizados. Diseñé e implementé un sistema de diseño integral con componentes reutilizables que aceleró los ciclos de desarrollo. Desarrollé servicios backend robustos con C#, ASP.NET y Entity Framework, estableciendo arquitecturas escalables para aplicaciones empresariales. Optimicé el rendimiento mediante lazy loading, code splitting y administración de contenedores Docker con PostgreSQL."},{"company":"SSUT Tarija","position":"Ingeniero de Software","period":"Nov 2023 - May 2024","description":"Desarrollé aplicaciones móviles con Flutter implementando funcionalidades complejas y UI responsiva con widgets personalizados adaptados a diferentes tamaños de pantalla. Creé y mantuve biblioteca de componentes reutilizables con Widgetbook para pruebas visuales, documentación técnica y aseguramiento de calidad del código. Programé la lógica del servidor con C# y ASP.NET MVC integrándose con PostgreSQL para servicios web robustos. Gestioné control de versiones y flujos CI/CD con Git y GitLab, implementando pipelines automatizados para testing y deployment continuo."},{"company":"UAJMS","position":"Desarrollador Web / UI Engineer","period":"Jul 2014 - Sep 2016","description":"Desarrollé y mantuve sitios web institucionales dinámicos utilizando PHP, JavaScript, CSS y CMS como WordPress y Drupal. Administré y configuré servidores web Linux (Apache, Nginx) para optimizar disponibilidad, rendimiento y seguridad. Gestioné bases de datos MySQL asegurando integridad de datos y optimización de consultas. Creé interfaces personalizadas transformando diseños en código HTML5/CSS3 semántico y accesible, asegurando compatibilidad cross-browser y experiencia de usuario óptima en diferentes dispositivos."},{"company":"GRAPHICART","position":"Desarrollador Frontend","period":"Oct 2011 - Jun 2014","description":"Desarrollé aplicaciones web dinámicas integrando PHP, Ruby on Rails y JavaScript con MySQL para soluciones empresariales robustas. Transformé diseños gráficos de Photoshop e Illustrator a maquetaciones web semánticas en HTML5/CSS3 con SASS, asegurando fidelidad visual. Optimicé el rendimiento frontend mediante minificación, compresión de assets y estrategias de caché. Resolví problemas de compatibilidad cross-browser mientras creaba interfaces intuitivas y responsivas que se adaptaban a diferentes dispositivos y tamaños de pantalla."},{"company":"EL NACIONAL","position":"Junior DevOps Engineer","period":"Mar 2008 - Sep 2011","description":"Desarrollé y personalicé sistemas de gestión de contenidos (CMS) basados en PHP para publicación diaria de noticias. Administré servidores Linux Debian realizando configuraciones de seguridad, monitoreo de rendimiento y mantenimiento preventivo. Ejecuté copias de seguridad automatizadas y restauración de bases de datos MySQL, garantizando integridad de información crítica. Documenté procesos técnicos y solucioné incidencias críticas del sistema bajo presión de deadlines de publicación diaria del periódico."}]},{"name":"designer","title":"Diseñador UI/UX & Product Designer","subtitles":["UI/UX Strategy","Digital Product Design","User Experience"],"summary":"Diseñador UI/UX y Product Designer con 18 años de experiencia creando experiencias digitales centradas en el usuario. Especializado en diseño de interfaces intuitivas, sistemas de diseño escalables y prototipado interactivo de alta fidelidad. Experto en herramientas modernas de diseño incluyendo Figma, Affinity (Canva) y Adobe Creative Suite para producción profesional y colaborativa. Experiencia traduciendo necesidades del negocio en soluciones visuales efectivas que mejoran la usabilidad y satisfacción del usuario en proyectos web y móviles.","skills":[{"category":"Diseño","items":["Figma","Affinity (Canva)","Adobe XD","Sketch","Wireframing","Prototipado Interactivo","Design Systems"]},{"category":"Visual","items":["Photoshop","Illustrator","InDesign","Teoría del Color","Tipografía","Composición Visual"]},{"category":"Web","items":["HTML5","CSS3","Svelte","Vue.js","JavaScript","Responsive Design"]},{"category":"Metodología","items":["Design Thinking","Scrum","User Research","Arquitectura de Información","Usability Testing"]},{"category":"Producto & IA","items":["Google Stitch","Diseño asistido por IA","Design Tokens","Handoff técnico","Workshops de Design Thinking"]}],"experiences":[{"company":"Freelance & Actualización Tecnológica","position":"Freelance Designer","period":"Dic 2024 - Jun 2026","description":"Durante el período independiente trabajé en sistemas de diseño en Figma con tokens, componentes reutilizables, documentación y handoff técnico; prototipado UX con Google Stitch; integración de Midjourney, Adobe Firefly, Claude y Gemini en flujos creativos; e identidades visuales y branding para proyectos independientes. Formación intensiva en inglés técnico: A2."},{"company":"ITGroup Systems","position":"Product Designer / UI Lead","period":"Oct 2016 - Dic 2024","description":"Definí lineamientos visuales, identidad de marca y estrategia de diseño para productos digitales asegurando consistencia. Diseñé y desarrollé un sistema de diseño completo en Figma con componentes y documentación que aceleró el proceso de diseño-desarrollo. Creé prototipos interactivos de alta fidelidad para validar conceptos, lideré workshops de Design Thinking y realicé investigación de usuarios para resolver problemas complejos de UX."},{"company":"SSUT Tarija","position":"Diseñador UI/UX","period":"Nov 2023 - May 2024","description":"Diseñé experiencias de usuario completas para aplicaciones móviles en Flutter, desde wireframes hasta prototipos finales de alta fidelidad en Figma. Creé user flows, journey maps e información arquitectónica para identificar puntos de dolor y optimizar la experiencia del usuario final. Desarrollé biblioteca de componentes UI reutilizables con documentación detallada, realicé pruebas de usabilidad iterativas y coordiné la entrega de assets y especificaciones técnicas al equipo de desarrollo."},{"company":"UAJMS","position":"Diseñador UI/UX & Web","period":"Jul 2014 - Sep 2016","description":"Diseñé interfaces de usuario para sitios web institucionales asegurando accesibilidad y usabilidad óptima. Creé wireframes, mockups y prototipos visuales con Photoshop e Illustrator, validando conceptos antes del desarrollo. Gestioné contenido y optimicé la experiencia de usuario en WordPress para portales de alta concurrencia, desarrollando guías de estilo visual y piezas de comunicación digital manteniendo consistencia en la identidad visual."},{"company":"GRAPHICART","position":"Diseñador Web / Gráfico","period":"Oct 2011 - Jun 2014","description":"Conceptualicé y diseñé interfaces web intuitivas para sitios corporativos y aplicaciones comerciales, optimizadas para conversión y engagement. Desarrollé identidades de marca completas incluyendo logotipos, paletas de colores y papelería corporativa. Diseñé material publicitario digital aplicando principios de diseño responsivo para diferentes dispositivos, colaborando estrechamente con clientes para traducir necesidades del negocio en soluciones visuales efectivas."},{"company":"EL NACIONAL","position":"Diseñador Web","period":"Mar 2008 - Sep 2011","description":"Gestioné el diseño visual, maquetación y actualización de contenido en el portal web institucional del periódico digital. Creé banners publicitarios, piezas gráficas para campañas digitales y newsletters optimizadas para web. Edité y optimicé imágenes digitales con Photoshop para mejorar el rendimiento de carga, manteniendo la identidad visual del periódico y asegurando coherencia estética en todas las plataformas."}]},{"name":"graphic","title":"Diseñador Gráfico Integral (Digital & Off-set)","subtitles":["Diseño Gráfico","Digital & Off-set"],"summary":"Diseñador Gráfico Multimedia con 18 años de experiencia en diseño digital y producción impresa. Especializado en creación de identidades visuales de marca, diseño editorial y producción para imprenta offset y serigrafía. Experto en Adobe Creative Suite y Affinity (Canva) para producción profesional de alto nivel. Amplia experiencia gestionando proyectos desde la conceptualización hasta la producción final, coordinando con proveedores de imprenta y asegurando calidad técnica en medios digitales, offset y serigrafía.","skills":[{"category":"Diseño Gráfico","items":["Adobe Photoshop","Illustrator","InDesign","Affinity (Canva)"]},{"category":"Producción Impresa","items":["Preprensa","Offset","Serigrafía","CMYK/Pantone","Separación de colores","Tipografía","Diagramación editorial"]},{"category":"Web & Digital","items":["WordPress","Figma","Edición de imagen para web"]},{"category":"Branding","items":["Diseño de logotipos","Identidad corporativa","Papelería"]}],"experiences":[{"company":"Freelance & Actualización Tecnológica","position":"Freelance Graphic Designer","period":"Dic 2024 - Jun 2026","description":"Durante el período independiente desarrollé identidades visuales, logotipos, manuales de marca y piezas digitales e impresas; preparé materiales para offset con gestión de color CMYK/Pantone; y exploré herramientas de IA generativa como apoyo a la creación de assets y la iteración creativa. Formación intensiva en inglés técnico: A2."},{"company":"GRAPHICART","position":"Diseñador Gráfico","period":"Oct 2011 - Jun 2014","description":"Creé identidades de marca completas incluyendo logotipos, manuales de identidad corporativa y material promocional para diversos clientes. Diseñé y diagramé material publicitario para impresión offset, serigrafía y gran formato: folletos, catálogos, vallas, vinilos y textiles estampados. Gestioné el proceso de preprensa y producción en serigrafía con separación de colores, preparando archivos con especificaciones técnicas para sangrado, resolución y gestión de color CMYK/Pantone. Coordiné con proveedores para asegurar calidad de impresión final."},{"company":"ITGroup Systems","position":"Diseñador de Producto","period":"Oct 2016 - Dic 2024","description":"Definí y mantuve la identidad visual corporativa, lineamientos de marca y guías de estilo para todos los productos y comunicaciones de la empresa. Creé sistemas de diseño visuales, assets gráficos, iconografía y elementos visuales para interfaces de software y aplicaciones web. Diseñé material gráfico digital incluyendo banners, gráficos para redes sociales y presentaciones corporativas, supervisando la calidad estética de todos los entregables digitales y asegurando coherencia visual en toda la marca."},{"company":"SSUT Tarija","position":"Diseñador de Interfaces","period":"Nov 2023 - May 2024","description":"Diseñé interfaces visuales, iconografía personalizada y elementos gráficos cohesivos para aplicaciones móviles en Flutter. Creé composiciones visuales, layouts de pantallas y mockups de alta calidad para guiar el desarrollo del software. Adapté y optimicé gráficos y assets digitales para asegurar su correcto renderizado en diferentes dispositivos, colaborando en la definición de paleta de colores, tipografía y sistema visual completo del producto digital."},{"company":"UAJMS","position":"Diseñador Gráfico / Web","period":"Jul 2014 - Sep 2016","description":"Diseñé material promocional universitario para eventos académicos y campañas institucionales: flyers, afiches, banners y pendones. Realicé retoque fotográfico profesional, composición digital y manipulación creativa de imágenes en Adobe Photoshop para contenido web y publicaciones. Gestioné el diseño visual y maquetación de contenidos del portal web institucional, manteniendo la coherencia visual de la identidad gráfica universitaria en diversos medios digitales e impresos."},{"company":"EL NACIONAL","position":"Diseñador Digital / Producción Offset","period":"Mar 2008 - Sep 2011","description":"Diseñé banners publicitarios, infografías periodísticas y piezas gráficas para el periódico digital y campañas online bajo plazos ajustados diarios. Preparé archivos y coordiné la producción offset del periódico impreso, asegurando especificaciones técnicas de registro de color, sangrado y marcas de corte. Optimicé y edité imágenes fotográficas para publicación digital e impresa, manteniendo el diseño visual del sitio web y creando diagramaciones para documentos y boletines informativos con coherencia de marca."}]},{"name":"analyst","title":"Analista de Aplicaciones de Negocio","subtitles":["Análisis funcional","Soporte de aplicaciones","Documentación y mejora de procesos"],"summary":"Analista de aplicaciones de negocio con experiencia conectando áreas usuarias y equipos técnicos. Trabajo con relevamiento de requerimientos, análisis de impacto, soporte funcional, gestión de incidentes y documentación de soluciones en entornos empresariales.","skills":[{"category":"Análisis & Negocio","items":["Análisis funcional","Relevamiento de requerimientos","Modelado AS-IS/TO-BE","Análisis de impacto","Gestión de incidentes","Soporte funcional","Capacitación de usuarios","Documentación funcional"]},{"category":"Aplicaciones & Datos","items":["Oracle EBS","Facturación DIO","Aranda","SQL","PL/SQL","PostgreSQL","Consultas complejas","Procedimientos almacenados"]},{"category":"Herramientas & UX","items":["Figma","Google Stitch","Claude","Gemini","Prototipado de flujos"]}],"experiences":[{"company":"MAMAYATECH","position":"Analista de Negocio · Soporte Funcional","period":"Jul 2026 - Presente","description":"Brindo soporte funcional a Oracle EBS, Facturación DIO, puntos de venta y Aranda. Gestiono incidentes, accesos y seguimiento de casos; valido requerimientos y cambios; documento diagnósticos y soluciones; y coordino con áreas usuarias, Base de Datos, Redes, Infraestructura y Desarrollo para mantener la continuidad operativa."},{"company":"ITGroup Systems","position":"Analista Funcional / Líder de Producto","period":"Oct 2016 - Dic 2024","description":"Lideré el relevamiento de requerimientos con usuarios clave y el modelado AS-IS/TO-BE. Brindé soporte funcional a sistemas web y móviles, coordiné integraciones, administré PostgreSQL para reportes y elaboré manuales técnicos y de usuario, capacitaciones y soporte post-implantación."},{"company":"SSUT Tarija","position":"Analista de Sistemas · Ingeniero de Software","period":"Nov 2023 - May 2024","description":"Realicé análisis funcional y diseño de experiencias para aplicaciones Flutter: relevamiento, definición de requerimientos, prototipos UX, pruebas funcionales iterativas, documentación técnica y soporte durante la implantación. Gestioné versiones y flujos CI/CD con Git y GitLab."},{"company":"UAJMS","position":"Analista y Desarrollador Web","period":"Jul 2014 - Sep 2016","description":"Relevé requerimientos institucionales, brindé soporte funcional y atención a usuarios del portal web, capacité a personal administrativo y colaboré en la gestión de servidores Linux."},{"company":"GRAPHICART","position":"Analista de Soluciones · Desarrollador Web","period":"Oct 2011 - Jun 2014","description":"Analicé requerimientos, diseñé soluciones web y brindé soporte post-entrega para clientes, coordinando ajustes y necesidades funcionales con los equipos involucrados."},{"company":"EL NACIONAL","position":"Soporte de Sistemas · Desarrollador Web","period":"Mar 2008 - Sep 2011","description":"Brindé soporte técnico y funcional a sistemas CMS, administré servidores Linux Debian y bases de datos MySQL, y atendí incidencias de publicación bajo plazos operativos diarios."}]},{"name":"teacher","title":"Docente de Diseño Digital","subtitles":["Diseño digital","Producción gráfica","Formación práctica"],"summary":"Docente de diseño digital con experiencia profesional en interfaces, identidad visual y producción gráfica para medios digitales e impresión. Integro fundamentos de diseño con procesos, herramientas y criterios técnicos de entrega.","skills":[{"category":"Diseño & Comunicación","items":["Diseño digital","Diseño gráfico","Diseño UI/UX","Figma","Photoshop","Illustrator","InDesign","Tipografía","Composición visual"]},{"category":"Producción Gráfica","items":["Preprensa","Offset","Serigrafía","CMYK/Pantone","Separación de colores","Diagramación editorial"]},{"category":"Docencia","items":["Planificación didáctica","Capacitación","Manuales y guías","Acompañamiento de aprendizaje","Evaluación de entregables"]}],"experiences":[{"company":"Experiencia profesional transversal","position":"Diseñador Digital / Gráfico","period":"Mar 2008 - Jun 2026","description":"Experiencia aplicada en diseño de interfaces, identidad visual, producción de piezas digitales e impresas, preparación de archivos para impresión y documentación de procesos. Esta trayectoria profesional constituye el contexto práctico para la enseñanza de diseño digital y producción gráfica."}]}]}', 'src/lib/data/cv.es.toml') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('es', 'site', '{"meta":{"tagline":"Habilidades · Experiencia · Diseño de Producto","description":"18 años de experiencia conectando desarrollo de software, diseño de producto, análisis funcional y comunicación visual. Explora habilidades respaldadas por responsabilidades profesionales."},"nav":{"theme_toggle_aria":"Cambiar tema","main_aria":"Navegación principal","skip_to_content":"Saltar al contenido","lang_toggle_aria":"Cambiar idioma"},"home":{"topbar":"Habilidades y experiencia","eyebrow":"Práctica profesional","explore_title":"Explora el sitio","skills_label":"Habilidades","skills_text":"Explora habilidades a través de experiencia profesional","experience_label":"Experiencia","experience_text":"Recorre puestos, responsabilidades y trayectoria","contact_title":"Contacto","email_label":"Correo electrónico","linkedin_label":"LinkedIn","education_title":"Formación"},"footer":{"bio":"Experiencia interdisciplinaria en software, diseño de producto, análisis funcional y comunicación visual. Habilidades conectadas con puestos y responsabilidades reales.","sections":{"links":{"title":"Enlaces","links":[{"label":"Sitio web","href_key":"website","icon":"language"},{"label":"Behance","href_key":"behance","icon":"palette"},{"label":"GitHub","href_key":"github","icon":"code"}]},"contact":{"title":"Contacto","links":[{"label":"LinkedIn","href_key":"linkedin","icon":"open_in_new"},{"label":"WhatsApp","href_key":"whatsapp","icon":"chat","accent":true},{"label":"Correo electrónico","href_key":"email","icon":"mail","mailto":true},{"label":"Tarija, Bolivia","href_key":"maps","icon":"location_on"}]}}}}', 'src/lib/data/site.es.toml') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('es', 'skill_stories', '{"figma":"Mi experiencia con Figma combina diseño de producto y colaboración con desarrollo. En ITGroup Systems trabajé como Product Designer / UI Lead y construí un sistema de diseño con componentes, tokens, documentación y guías de estilo. En SSUT Tarija diseñé flujos y prototipos de aplicaciones móviles y preparé bibliotecas de componentes y especificaciones para el equipo Flutter. En mi trabajo independiente continué con prototipado UX y handoff técnico.","design-systems":"He trabajado los sistemas de diseño como una herramienta de consistencia y colaboración, no solo como una biblioteca visual. En ITGroup Systems definí componentes reutilizables, tokens, documentación y guías de estilo para los productos digitales. En proyectos independientes reforcé el proceso de handoff para que las decisiones de diseño pudieran trasladarse con claridad a la implementación.","svelte":"En ITGroup Systems lideré el desarrollo frontend de aplicaciones web empresariales utilizando Svelte junto con Vue.js y Blazor. Mi trabajo se centró en interfaces escalables, componentes reutilizables y optimización del rendimiento mediante prácticas como lazy loading y code splitting, coordinando el trabajo frontend con servicios backend y necesidades del producto.","kotlin":"En trabajo independiente desarrollé aplicaciones financieras nativas para Android con Kotlin y Jetpack Compose. El alcance descrito en mi CV incluye arquitecturas MVVM/MVI, integración con Firebase, despliegues en Google Cloud Run y Firebase App Distribution, autenticación segura y flujos reactivos con Coroutines y Flow para dashboards y transacciones.","elixir-otp":"En trabajo independiente desarrollé chatbots interactivos de alta concurrencia con Elixir/OTP y Phoenix Framework, integrados con WhatsApp Business API. El trabajo incluyó arquitectura de mensajería tolerante a fallos basada en el modelo de actores, despliegue en Fly.io, pipelines CI/CD y monitoreo de disponibilidad.","analisis-funcional":"Mi análisis funcional conecta necesidades de usuarios con decisiones técnicas. En MAMAYATECH relevo y documento requerimientos, analizo impactos, gestiono incidentes y valido cambios funcionales, coordinando con áreas usuarias y equipos de Base de Datos, Redes, Infraestructura y Desarrollo. En ITGroup Systems trabajé con relevamiento de requerimientos y modelado AS-IS/TO-BE, además de soporte post-implantación y documentación.","oracle-ebs":"En MAMAYATECH brindo soporte funcional a Oracle EBS dentro de la operación de aplicaciones de negocio. Mi responsabilidad incluye diagnóstico y seguimiento de incidentes, análisis de impacto, validación de cambios, documentación de soluciones y coordinación con equipos técnicos cuando un caso requiere escalamiento. Mantengo los ejemplos deliberadamente generales para no exponer datos operativos.","gestion-de-incidentes":"En mi puesto actual en MAMAYATECH gestiono incidentes desde la recepción y el diagnóstico inicial hasta el seguimiento y cierre con el usuario. Identifico si el caso corresponde a soporte funcional, infraestructura, redes, base de datos o desarrollo; documento diagnósticos y soluciones en Aranda y coordino con los equipos responsables para mantener la continuidad operativa.","incident-management":"En mi puesto actual en MAMAYATECH gestiono incidentes desde la recepción y el diagnóstico inicial hasta el seguimiento y cierre con el usuario. Identifico si el caso corresponde a soporte funcional, infraestructura, redes, base de datos o desarrollo; documento diagnósticos y soluciones en Aranda y coordino con los equipos responsables para mantener la continuidad operativa.","preprensa":"Mi experiencia en preprensa se desarrolló en trabajos de diseño gráfico y producción impresa, especialmente en GRAPHICART y EL NACIONAL. Preparé archivos para offset y serigrafía considerando sangrado, separación de colores, registro y gestión CMYK/Pantone, y coordiné con proveedores para que las piezas cumplieran las especificaciones de producción.","wordpress":"He trabajado con WordPress en desarrollo web institucional y en implementación de tiendas digitales. En mi experiencia independiente incorporé WooCommerce, Elementor y WP-CLI para personalizar sitios, automatizar tareas de instalación y mantenimiento y atender rendimiento, SEO técnico y experiencia adaptable a distintos dispositivos."}', 'src/lib/data/skill-stories.ts') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('en', 'cv', '{"personal":{"name":"Benito Anagua","location":"Tarija, Bolivia","phone":"+591 72945548","email":"benito.anagua@gmail.com","website":"https://benitoanagua.pages.dev/","linkedin":"https://www.linkedin.com/in/benito-anagua","github":"https://github.com/benitoanagua","behance":"https://behance.net/benitoanagua","whatsapp":"https://wa.me/59172945548","maps":"https://www.google.com/maps/place/Tarija,+Bolivia"},"education":[{"degree":"Bachelor''s Degree in Computer Engineering","institution":"Universidad Autónoma Juan Misael Saracho","year":"2012"},{"degree":"English — A2","institution":"Funval International","year":"2025"}],"focuses":[{"name":"developer","title":"Senior Full Stack & Frontend Developer","subtitles":["Full Stack Development","Modern Web Architecture","Frontend Leadership"],"summary":"Senior Full Stack Developer with 18 years of experience in modern web development, specialized in Frontend. Expert in creating scalable, responsive, and high-performance user interfaces using Svelte, Vue.js, and Blazor. Extensive experience in frontend architecture, web application optimization, and reusable component system development. Experience leading technical projects, implementing development best practices, and collaborating with multidisciplinary teams throughout the complete SDLC.","skills":[{"category":"Frontend","items":["Svelte","Vue.js","Blazor","Astro.js","Flutter","HTML5","CSS3/SASS","JavaScript","TypeScript"]},{"category":"Backend","items":["C#","ASP.NET MVC","Entity Framework","PHP","Node.js","RESTful APIs"]},{"category":"Data & DevOps","items":["PostgreSQL","MySQL","Docker","Ubuntu Server","Nginx","Git","GitLab","CI/CD"]},{"category":"Design","items":["Figma","Design Systems","Prototyping","Responsive Design"]},{"category":"Mobile, AI & Automation","items":["Kotlin","Jetpack Compose","Firebase","Google Cloud Run","Elixir/OTP","Phoenix Framework","WhatsApp Business API","WooCommerce","WP-CLI","Claude","Gemini","Google Stitch"]}],"experiences":[{"company":"Freelance Developer & Technology Updates","period":"Dec 2024 - Jun 2026","position":"Freelance Developer","description":"During independent work, I developed Android mobile experiences with Kotlin and Jetpack Compose, integrated Firebase and Google Cloud deployments, built conversational flows with Elixir/OTP, Phoenix and WhatsApp Business API, and implemented WordPress/WooCommerce stores with Elementor and WP-CLI. I also incorporated Claude, OpenCode, Gemini and Google Stitch into analysis, development and UX prototyping workflows. Technical English training: A2."},{"company":"ITGroup Systems","period":"Oct 2016 - Dec 2024","position":"Full Stack Developer / Frontend Lead","description":"Led frontend development of enterprise web applications using Svelte, Vue.js, and Blazor, achieving high-performance interfaces and optimized load times. Designed and implemented a comprehensive design system with reusable components that accelerated development cycles. Developed robust backend services with C#, ASP.NET, and Entity Framework, establishing scalable architectures for enterprise applications. Optimized performance through lazy loading, code splitting, and Docker container management with PostgreSQL."},{"company":"SSUT Tarija","period":"Nov 2023 - May 2024","position":"Software Engineer","description":"Developed mobile applications with Flutter implementing complex functionalities and responsive UI with custom widgets adapted to different screen sizes. Created and maintained a library of reusable components with Widgetbook for visual testing, technical documentation, and code quality assurance. Programmed server logic with C# and ASP.NET MVC integrating with PostgreSQL for robust web services. Managed version control and CI/CD workflows with Git and GitLab, implementing automated pipelines for testing and continuous deployment."},{"company":"UAJMS","period":"Jul 2014 - Sep 2016","position":"Web Developer / UI Engineer","description":"Developed and maintained dynamic institutional websites using PHP, JavaScript, CSS, and CMS platforms like WordPress and Drupal. Administered and configured Linux web servers (Apache, Nginx) to optimize availability, performance, and security. Managed MySQL databases ensuring data integrity and query optimization. Created custom interfaces transforming designs into semantic and accessible HTML5/CSS3 code, ensuring cross-browser compatibility and optimal user experience across different devices."},{"company":"GRAPHICART","period":"Oct 2011 - Jun 2014","position":"Frontend Developer","description":"Developed dynamic web applications integrating PHP, Ruby on Rails, and JavaScript with MySQL for robust enterprise solutions. Transformed graphic designs from Photoshop and Illustrator into semantic HTML5/CSS3 web layouts with SASS, ensuring visual fidelity. Optimized frontend performance through minification, asset compression, and caching strategies. Resolved cross-browser compatibility issues while creating intuitive and responsive interfaces that adapted to different devices and screen sizes."},{"company":"EL NACIONAL","period":"Mar 2008 - Sep 2011","position":"Junior DevOps Engineer","description":"Developed and customized content management systems (CMS) based on PHP for daily news publishing. Administered Debian Linux servers performing security configurations, performance monitoring, and preventive maintenance. Executed automated backups and MySQL database restoration, ensuring critical information integrity. Documented technical processes and resolved critical system incidents under pressure of daily newspaper publication deadlines."}]},{"name":"designer","title":"UI/UX Designer & Product Designer","subtitles":["UI/UX Strategy","Digital Product Design","User Experience"],"summary":"UI/UX Designer and Product Designer with 18 years of experience creating user-centered digital experiences. Specialized in intuitive interface design, scalable design systems, and high-fidelity interactive prototyping. Expert in modern design tools including Figma, Affinity (Canva), and Adobe Creative Suite for professional and collaborative production. Experience translating business needs into effective visual solutions that improve usability and user satisfaction in web and mobile projects.","skills":[{"category":"Design","items":["Figma","Affinity (Canva)","Adobe XD","Sketch","Wireframing","Interactive Prototyping","Design Systems"]},{"category":"Visual","items":["Photoshop","Illustrator","InDesign","Color Theory","Typography","Visual Composition"]},{"category":"Web","items":["HTML5","CSS3","Svelte","Vue.js","JavaScript","Responsive Design"]},{"category":"Methodology","items":["Design Thinking","Scrum","User Research","Information Architecture","Usability Testing"]},{"category":"Product & AI","items":["Google Stitch","AI-assisted design","Design Tokens","Technical Handoff","Design Thinking Workshops"]}],"experiences":[{"company":"Freelance Designer & Technology Updates","period":"Dec 2024 - Jun 2026","position":"Freelance Designer","description":"During independent work, I developed Figma design systems with tokens, reusable components, documentation and technical handoff; prototyped UX flows with Google Stitch; incorporated Midjourney, Adobe Firefly, Claude and Gemini into creative workflows; and created visual identities and branding for independent work. Technical English training: A2."},{"company":"ITGroup Systems","period":"Oct 2016 - Dec 2024","position":"Product Designer / UI Lead","description":"Defined visual guidelines, brand identity, and design strategy for digital products ensuring consistency. Designed and developed a complete design system in Figma with components and documentation that accelerated the design-development process. Created high-fidelity interactive prototypes to validate concepts, led Design Thinking workshops, and conducted user research to solve complex UX problems."},{"company":"SSUT Tarija","period":"Nov 2023 - May 2024","position":"UI/UX Designer","description":"Designed complete user experiences for Flutter mobile applications, from wireframes to final high-fidelity prototypes in Figma. Created user flows, journey maps, and information architecture to identify pain points and optimize the end-user experience. Developed a library of reusable UI components with detailed documentation, conducted iterative usability testing, and coordinated asset delivery and technical specifications to the development team."},{"company":"UAJMS","period":"Jul 2014 - Sep 2016","position":"UI/UX & Web Designer","description":"Designed user interfaces for institutional websites ensuring optimal accessibility and usability. Created wireframes, mockups, and visual prototypes with Photoshop and Illustrator, validating concepts before development. Managed content and optimized user experience in WordPress for high-traffic portals, developing visual style guides and digital communication pieces while maintaining consistency in visual identity."},{"company":"GRAPHICART","period":"Oct 2011 - Jun 2014","position":"Web / Graphic Designer","description":"Conceptualicé y diseñé interfaces web intuitivas para sitios corporativos y aplicaciones comerciales, optimizadas para conversión y engagement. Desarrollé identidades de marca completas incluyendo logotipos, paletas de colores y papelería corporativa. Diseñé material publicitario digital aplicando principios de diseño responsivo para diferentes dispositivos, colaborando estrechamente con clientes para traducir necesidades del negocio en soluciones visuales efectivas."},{"company":"EL NACIONAL","period":"Mar 2008 - Sep 2011","position":"Web Designer","description":"Managed visual design, layout, and content updates for the digital newspaper''s institutional web portal. Created advertising banners, graphic pieces for digital campaigns, and web-optimized newsletters. Edited and optimized digital images with Photoshop to improve loading performance, maintaining the newspaper''s visual identity and ensuring aesthetic coherence across all platforms."}]},{"name":"graphic","title":"Integral Graphic Designer (Digital & Offset)","subtitles":["Graphic Design","Digital & Offset"],"summary":"Multimedia Graphic Designer with 18 years of experience in digital design and print production. Specialized in creating brand visual identities, editorial design, and production for offset and screen printing. Expert in Adobe Creative Suite and Affinity (Canva) for high-level professional production. Extensive experience managing projects from conceptualization to final production, coordinating with print vendors, and ensuring technical quality across digital, offset, and screen printing media.","skills":[{"category":"Graphic Design","items":["Adobe Photoshop","Illustrator","InDesign","Affinity (Canva)"]},{"category":"Print Production","items":["Prepress","Offset","Screen Printing","CMYK/Pantone","Color Separation","Typography","Editorial Layout"]},{"category":"Web & Digital","items":["WordPress","Figma","Image Editing for Web"]},{"category":"Branding","items":["Logo Design","Corporate Identity","Stationery"]}],"experiences":[{"company":"Freelance Graphic Designer & Technology Updates","period":"Dec 2024 - Jun 2026","position":"Freelance Graphic Designer","description":"During independent work, I created visual identities, logos, brand manuals and digital/print assets; prepared offset materials with CMYK/Pantone color management; and explored generative AI tools to support asset creation and creative iteration. Technical English training: A2."},{"company":"GRAPHICART","period":"Oct 2011 - Jun 2014","position":"Graphic Designer","description":"Created complete brand identities including logos, corporate identity manuals, and promotional material for diverse clients. Designed and laid out advertising material for offset printing, screen printing, and large format: brochures, catalogs, billboards, vinyl, and printed textiles. Managed the prepress and screen printing production process with color separation, preparing files with technical specifications for bleed, resolution, and CMYK/Pantone color management. Coordinated with vendors to ensure final print quality."},{"company":"ITGroup Systems","period":"Oct 2016 - Dec 2024","position":"Product Designer","description":"Defined and maintained corporate visual identity, brand guidelines, and style guides for all company products and communications. Created visual design systems, graphic assets, iconography, and visual elements for software interfaces and web applications. Designed digital graphic material including banners, social media graphics, and corporate presentations, supervising the aesthetic quality of all digital deliverables and ensuring visual coherence across the brand."},{"company":"SSUT Tarija","period":"Nov 2023 - May 2024","position":"Interface Designer","description":"Designed visual interfaces, custom iconography, and cohesive graphic elements for Flutter mobile applications. Created visual compositions, screen layouts, and high-quality mockups to guide software development. Adapted and optimized graphics and digital assets to ensure correct rendering across different devices, collaborating on the definition of color palette, typography, and complete visual system of the digital product."},{"company":"UAJMS","period":"Jul 2014 - Sep 2016","position":"Graphic / Web Designer","description":"Designed university promotional material for academic events and institutional campaigns: flyers, posters, banners, and pennants. Performed professional photo retouching, digital compositing, and creative image manipulation in Adobe Photoshop for web content and publications. Managed visual design and content layout for the institutional web portal, maintaining the visual coherence of the university''s graphic identity across various digital and print media."},{"company":"EL NACIONAL","period":"Mar 2008 - Sep 2011","position":"Digital Designer / Offset Production","description":"Designed advertising banners, journalistic infographics, and graphic pieces for the digital newspaper and online campaigns under tight daily deadlines. Prepared files and coordinated offset production of the printed newspaper, ensuring technical specifications for color registration, bleed, and crop marks. Optimized and edited photographic images for digital and print publication, maintaining the website''s visual design and creating layouts for documents and newsletters with brand consistency."}]},{"name":"analyst","title":"Business Applications Analyst","subtitles":["Functional analysis","Application support","Process documentation and improvement"],"summary":"Business applications analyst connecting user departments with technical teams. Experienced in requirements gathering, impact analysis, functional support, incident management and solution documentation in enterprise environments.","skills":[{"category":"Business & Analysis","items":["Functional Analysis","Requirements Gathering","AS-IS/TO-BE Modeling","Impact Analysis","Incident Management","Functional Support","User Training","Functional Documentation"]},{"category":"Applications & Data","items":["Oracle EBS","DIO Billing","Aranda","SQL","PL/SQL","PostgreSQL","Complex Queries","Stored Procedures"]},{"category":"Tools & UX","items":["Figma","Google Stitch","Claude","Gemini","Workflow Prototyping"]}],"experiences":[{"company":"MAMAYATECH","position":"Business Analyst · Functional Support","period":"Jul 2026 - Present","description":"Provide functional support for Oracle EBS, DIO Billing, point-of-sale systems and Aranda. Manage incidents, access and case follow-up; validate requirements and changes; document diagnostics and solutions; and coordinate with users, Database, Networks, Infrastructure and Development teams to maintain operational continuity."},{"company":"ITGroup Systems","position":"Functional Analyst / Product Lead","period":"Oct 2016 - Dec 2024","description":"Led requirements gathering with key users and AS-IS/TO-BE modeling. Supported enterprise web and mobile systems, coordinated integrations, administered PostgreSQL reporting and produced technical/user manuals, training and post-implementation support."},{"company":"SSUT Tarija","position":"Systems Analyst · Software Engineer","period":"Nov 2023 - May 2024","description":"Performed functional analysis and experience design for Flutter applications: requirements gathering, UX prototypes, iterative functional testing, technical documentation and implementation support. Managed version control and CI/CD workflows with Git and GitLab."},{"company":"UAJMS","position":"Web Analyst and Developer","period":"Jul 2014 - Sep 2016","description":"Gathered institutional requirements, provided functional support and user assistance for the institutional web portal, trained administrative staff and contributed to Linux server administration."},{"company":"GRAPHICART","position":"Solutions Analyst · Web Developer","period":"Oct 2011 - Jun 2014","description":"Analyzed requirements, designed web solutions and provided post-delivery support for clients, coordinating functional adjustments with the teams involved."},{"company":"EL NACIONAL","position":"Systems Support · Web Developer","period":"Mar 2008 - Sep 2011","description":"Provided technical and functional support for CMS systems, administered Debian Linux servers and MySQL databases, and handled publishing incidents under daily operational deadlines."}]},{"name":"teacher","title":"Digital Design Instructor","subtitles":["Digital design","Graphic production","Practical learning"],"summary":"Digital design instructor with professional experience in interfaces, visual identity and graphic production for digital media and print. Connects design fundamentals with practical workflows, tools and technical delivery criteria.","skills":[{"category":"Design & Communication","items":["Digital Design","Graphic Design","UI/UX Design","Figma","Photoshop","Illustrator","InDesign","Typography","Visual Composition"]},{"category":"Graphic Production","items":["Prepress","Offset Printing","Screen Printing","CMYK/Pantone","Color Separation","Editorial Layout"]},{"category":"Teaching","items":["Instructional Planning","Training","Manuals and Guides","Learning Support","Deliverable Assessment"]}],"experiences":[{"company":"Cross-disciplinary professional experience","position":"Digital / Graphic Designer","period":"Mar 2008 - Jun 2026","description":"Applied experience in interface design, visual identity, digital and print assets, print-ready file preparation and process documentation. This professional practice provides the practical context for teaching digital design and graphic production."}]}]}', 'src/lib/data/cv.en.toml') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('en', 'site', '{"meta":{"tagline":"Skills · Experience · Product Design","description":"18 years connecting software development, product design, functional analysis and visual communication. Explore skills backed by professional responsibilities."},"nav":{"theme_toggle_aria":"Toggle theme","main_aria":"Main navigation","skip_to_content":"Skip to content","lang_toggle_aria":"Change language"},"home":{"topbar":"Skills and experience","eyebrow":"Professional practice","explore_title":"Explore the site","skills_label":"Skills","skills_text":"Explore skills through professional evidence","experience_label":"Experience","experience_text":"Browse roles, responsibilities and career context","contact_title":"Contact","email_label":"Email","linkedin_label":"LinkedIn","education_title":"Education"},"footer":{"bio":"Interdisciplinary experience across software, product design, functional analysis and visual communication. Skills connected to real roles and responsibilities.","sections":{"links":{"title":"Links","links":[{"label":"Website","href_key":"website","icon":"language"},{"label":"Behance","href_key":"behance","icon":"palette"},{"label":"GitHub","href_key":"github","icon":"code"}]},"contact":{"title":"Contact","links":[{"label":"LinkedIn","href_key":"linkedin","icon":"open_in_new"},{"label":"WhatsApp","href_key":"whatsapp","icon":"chat","accent":true},{"label":"Email","href_key":"email","icon":"mail","mailto":true},{"label":"Tarija, Bolivia","href_key":"maps","icon":"location_on"}]}}}}', 'src/lib/data/site.en.toml') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
INSERT INTO portfolio_content (locale, content_key, payload_json, source_path) VALUES ('en', 'skill_stories', '{"figma":"My Figma practice combines product design and collaboration with engineering. At ITGroup Systems, as Product Designer / UI Lead, I built a design system with components, tokens, documentation and style guides. At SSUT Tarija, I designed flows and prototypes for mobile applications and prepared component libraries and specifications for the Flutter team. In independent work, I continued with UX prototyping and technical handoff.","design-systems":"I approach design systems as a tool for consistency and collaboration, not simply as a visual library. At ITGroup Systems, I defined reusable components, tokens, documentation and style guides for digital products. In independent work, I strengthened the handoff process so design decisions could be carried into implementation clearly.","svelte":"At ITGroup Systems, I led frontend development for enterprise web applications using Svelte alongside Vue.js and Blazor. My work focused on scalable interfaces, reusable components and performance optimization through practices such as lazy loading and code splitting, coordinating frontend work with backend services and product needs.","kotlin":"In independent work, I developed native Android financial applications with Kotlin and Jetpack Compose. The scope described in my CV includes MVVM/MVI architecture, Firebase integration, deployments through Google Cloud Run and Firebase App Distribution, secure authentication, and reactive Coroutines/Flow workflows for dashboards and transactions.","elixir-otp":"In independent work, I developed high-concurrency interactive chatbots with Elixir/OTP and Phoenix Framework, integrated with the WhatsApp Business API. The work included fault-tolerant messaging architecture based on the actor model, Fly.io deployment, CI/CD pipelines and availability monitoring.","analisis-funcional":"My functional analysis work connects user needs with technical decisions. At MAMAYATECH, I gather and document requirements, analyze impacts, manage incidents and validate functional changes, coordinating with user departments and Database, Networks, Infrastructure and Development teams. At ITGroup Systems, I worked on requirements gathering and AS-IS/TO-BE modeling, as well as post-implementation support and documentation.","oracle-ebs":"At MAMAYATECH, I provide functional support for Oracle EBS within business application operations. My responsibilities include incident diagnosis and follow-up, impact analysis, change validation, solution documentation and coordination with technical teams when a case needs escalation. Examples are intentionally general to avoid exposing operational data.","gestion-de-incidentes":"In my current role at MAMAYATECH, I manage incidents from intake and initial diagnosis through follow-up and user-confirmed closure. I identify whether a case belongs to functional support, infrastructure, networks, database or development; document diagnostics and solutions in Aranda; and coordinate with the responsible teams to maintain operational continuity.","incident-management":"In my current role at MAMAYATECH, I manage incidents from intake and initial diagnosis through follow-up and user-confirmed closure. I identify whether a case belongs to functional support, infrastructure, networks, database or development; document diagnostics and solutions in Aranda; and coordinate with the responsible teams to maintain operational continuity.","preprensa":"My prepress experience comes from graphic design and print production work, especially at GRAPHICART and EL NACIONAL. I prepared offset and screen-printing files with bleed, color separation, registration and CMYK/Pantone management in mind, and coordinated with suppliers to meet production specifications.","wordpress":"I have worked with WordPress in institutional web development and digital store implementation. In independent work, I used WooCommerce, Elementor and WP-CLI to customize sites, automate setup and maintenance tasks, and address performance, technical SEO and cross-device experience."}', 'src/lib/data/skill-stories.ts') ON CONFLICT(locale, content_key) DO UPDATE SET payload_json = excluded.payload_json, source_path = excluded.source_path, updated_at = CURRENT_TIMESTAMP;
